In order to obtain the estimate, we make use of the following standard comparison of sum and integral; for all $j\in\mathbb{N}$
\begin{align*}
0\leq \left|\|Z_j\|_2^2-\sigma^2\right|&= \left|\sum_{ 2^{\sqrt{k}}\leq j \leq 2^k}\frac{1}{k\log k} -\int_{\log j}^{\log^2( j)}\frac{dx}{x\log x}\right|\\
&\lesssim \frac{2}{\left\lfloor{\log j}\right\rfloor(\log\left\lfloor{\log j}\right\rfloor)}+2\left(\sum_{k=\left\lceil{\log j}\right\rceil}^{\left\lceil{\log ^2(j)}\right\rceil}\frac{1}{k\log(k)} -\int_{\log(j)}^{\log^2(j)}\frac{dx}{x\log x}\right)\\
&\lesssim \frac{1}{(\log
	 j)(\log\log j)}.
\end{align*}  
Since for all $a,b\geq 0$, $(a-b)^2\leq |a^2-b^2|$,
\begin{align*}
\sum_{j=4}^n\left(\|Z_j\|_2-\sigma\right)^2&\leq \sum_{j=4}^n\left|\|Z_j\|_2^2-\sigma^2\right|\\
&\lesssim \sum_{j=4}^n\frac{1}{(\log j)(\log\log j)}\sim_{n\to\infty}\frac{n}{(\log n)(\log\log n)}, 
\end{align*}

\cite[Lemma 3.2]{MR2663640}\label{lem: Gouezel}
Let $u_n, v_n$ be two real sequences. Let $\mathscr{Z}_n : \Omega\to E_n$ and $\mathscr{Z}_n' : \Omega\to E_n'$
be two sequences of random variables, taking values
in separable Banach spaces. Assume that for any $N$ there exists a coupling
between $(\mathscr{Z}_1,\ldots,\mathscr{Z}_N)$ and $(\mathscr{Z}_1',\ldots,\mathscr{Z}_N')$ with
\begin{equation}\label{eq: Gouezel}
\mathbb{P}\left(|\mathscr{Z}_n-\mathscr{Z}_n'|\geq u_n\right)<v_n    
\end{equation}
for all $1\leq n\leq N$. Then there exists a coupling between $(\mathscr Z_k)_{k=1}^\infty$ and $(\mathscr Z_k')_{k=1}^\infty$ which satisfies \eqref{eq: Gouezel} for all $n\in\mathbb{N}$.

\label{lem: triple log} There exists a constant $C>0$ such that for all large $n$ the following holds: 
\begin{itemize}
\item[(a)] For all $\frac{n}{\log^2(n)}\leq j\leq n$,
\[
0\leq \lg_3 (n)-\lg_3(j)\leq \frac{C}{\log n} 
\]
 \item[(b)] For all $\frac{n}{\log\log n}\leq j\leq n$,
\[
0\leq \lg_3 (n)-\lg_3(j)\leq \frac{C\lg_3(n)}{(\log n)(\log\log n)} 
\]
\end{itemize}

The proof of (i) implies (ii) in \cite[Proposition 2.6.1]{MR3837109} shows that for a random variable $Y$, if there exists $K_1>0$ such that for all $t>0$,
\begin{equation}\label{eq: subGaussian}
\mathbb{P}(|Y|>t)\leq 2\exp(-t^2/K_1^2),
\end{equation}
then for all $p\geq 1$,
\begin{equation}\label{eq: Moment Vershynin}
\mathbb{E}(|Y|^p)\leq \beta^p(K_1)^p
\end{equation}
where $\beta$ is some global constant which does not depend on $p$ and (most importantly) on $K_1$. 

Now when $Z$ is a linear span of iid Rademacher random variables, Hoeffding inequality implies that it satisfies \eqref{eq: subGaussian} with $K_1=\sqrt{2\sum_{l=1}^La_l^2}$. The result follows by taking $p=6$ in \eqref{eq: Moment Vershynin}.
